3	 *
4	 * Pattern (per CLAUDE.md Phase 2):
5	 *   - Client actions use `requireUser()` -> cookie-bound `createClient()` so
6	 *     RLS enforces ownership.
7	 *   - Admin actions use `requireAdmin()` -> checks ADMIN_EMAILS env, then
8	 *     returns the cookie-bound client (for the auth identity) AND a paired
9	 *     service-role `createAdminClient()` for the actual mutation (admin pages
10	 *     read/write through service role, not RLS).
11	 */
12	// This file is server-only by transitive import: `@/lib/supabase/server` pulls
13	// in `next/headers`, which Next refuses to bundle into client components.
14	import { createClient, createAdminClient } from "@/lib/supabase/server";
15	import { isAdminEmail } from "@/lib/utils";
16	import type { SupabaseClient, User } from "@supabase/supabase-js";
17	import type { Database } from "@/lib/database.types";
18	
19	export type DBClient = SupabaseClient<Database>;
20	
21	/**
22	 * Resolve the current authed user via the cookie-bound client.
23	 * Returns `{ user, supabase }`. Throws `AuthError` if no user.
24	 */
25	export async function requireUser(): Promise<{ user: User; supabase: DBClient }> {
26	  const supabase = (await createClient()) as DBClient;
27	  const {
28	    data: { user }
29	  } = await supabase.auth.getUser();
30	  if (!user) {
31	    throw new AuthError("not_authenticated");
32	  }
33	  return { user, supabase };
34	}
