37	 * Resolve the current admin caller. Returns the user, the cookie-bound client
38	 * (RLS-respecting, used for identity/audit), AND a separate service-role
39	 * client for actual mutations (admin reads/writes bypass RLS by convention).
40	 */
41	export async function requireAdmin(): Promise<{
42	  user: User;
43	  supabase: DBClient;
44	  admin: DBClient;
45	}> {
46	  const { user, supabase } = await requireUser();
47	  if (!isAdminEmail(user.email)) {
48	    throw new AuthError("forbidden");
49	  }
50	  return { user, supabase, admin: createAdminClient() as DBClient };
51	}
52	
53	/**
54	 * Custom error used by server-action guards. Client-action call sites convert
55	 * these to `{ error }` return values; admin pages will surface them as 403/redirect.
56	 */
57	export class AuthError extends Error {
58	  readonly code: "not_authenticated" | "forbidden";
59	  constructor(code: "not_authenticated" | "forbidden") {
60	    super(code);
61	    this.code = code;
62	    this.name = "AuthError";
63	  }
