2	 * Company-scoped auth guards (multi-tenant layer).
3	 *
4	 * Pattern mirrors `auth.ts`: guards throw `AuthError` and return the
5	 * cookie-bound client so RLS stays the enforcement layer for member reads.
6	 * Role privilege is rank-based via the extensible `company_roles` catalog
7	 * (higher rank = more privilege; company_admin = 100), so new employer/role
8	 * types added as rows work without code changes.
9	 *
10	 * Server-only by transitive import of `@/lib/supabase/server` via `./auth`.
11	 */
12	import type { User } from "@supabase/supabase-js";
13	import { AuthError, requireUser, type DBClient } from "./auth";
14	
15	/** Rank of the company_admin role seeded in the tenancy migration. */
16	export const COMPANY_ADMIN_RANK = 100;
17	
18	export interface CompanyMembership {
19	  companyId: string;
20	  role: string;
21	  rank: number;
22	}
23	
24	export interface CompanyGuardResult {
25	  user: User;
26	  supabase: DBClient;
27	  membership: CompanyMembership;
28	}
29	
30	/**
31	 * Require the caller to be an ACTIVE member of `companyId` with role rank
32	 * >= `minRank`. Throws `AuthError("forbidden")` for non-members, inactive
33	 * memberships, and insufficient rank.
34	 */
35	export async function requireCompanyMember(
36	  companyId: string,
37	  minRank = 0
38	): Promise<CompanyGuardResult> {
39	  const { user, supabase } = await requireUser();
40	
41	  const { data: member, error } = await supabase
42	    .from("company_members")
43	    .select("role, status")
44	    .eq("company_id", companyId)
45	    .eq("user_id", user.id)
46	    .eq("status", "active")
47	    .single();
48	
49	  if (error || !member) {
50	    throw new AuthError("forbidden");
51	  }
52	
53	  const { data: role } = await supabase
54	    .from("company_roles")
55	    .select("rank")
56	    .eq("key", member.role)
57	    .single();
58	
59	  const rank = role?.rank ?? 0;
60	  if (rank < minRank) {
61	    throw new AuthError("forbidden");
62	  }
63	
64	  return {
65	    user,
66	    supabase,
67	    membership: { companyId, role: member.role, rank }
68	  };
69	}
