1	/**
2	 * Shared mock builders for server-action tests.
3	 * Keeps every action test file consistent without making any of them
4	 * depend on the others' state.
5	 */
6	import { vi } from "vitest";
7	
8	export type StubUser = { id: string; email: string };
9	
10	export interface StubTable {
11	  insert: ReturnType<typeof vi.fn>;
12	  update: ReturnType<typeof vi.fn>;
13	  delete: ReturnType<typeof vi.fn>;
14	  select: ReturnType<typeof vi.fn>;
15	  eq: ReturnType<typeof vi.fn>;
16	  single: ReturnType<typeof vi.fn>;
17	}
18	
19	/**
20	 * Build a thenable query builder where every method returns `this` and a
21	 * final `.single()` / await resolves to `{ data, error }`.
22	 *
23	 * Tests can assert against the call args of any method on the returned object.
24	 */
25	export function buildStubClient(opts: {
26	  user?: StubUser | null;
27	  // Per-table behavior: { insert?: {data,error}, update?: {error}, delete?: {error},
28	  // selectSingle?: {data,error}, selectMany?: {data,error} }.
29	  tables?: Record<
30	    string,
31	    {
32	      insert?: { data?: unknown; error?: { message: string } | null };
33	      update?: { data?: unknown; error?: { message: string } | null };
34	      delete?: { error?: { message: string } | null };
35	      selectSingle?: { data?: unknown; error?: { message: string } | null };
36	    }
37	  >;
38	}) {
39	  const tablesArg = opts.tables ?? {};
40	  const recorded: { table: string; method: string; args: unknown[] }[] = [];
41	
42	  function makeChain(
43	    table: string,
44	    terminal:
45	      | { kind: "insert"; data?: unknown; error?: { message: string } | null }
46	      | { kind: "update"; error?: { message: string } | null }
47	      | { kind: "delete"; error?: { message: string } | null }
48	      | { kind: "select"; data?: unknown; error?: { message: string } | null }
49	  ) {
50	    // The builder is itself awaitable AND has `.select().single()` / `.eq()` etc.
51	    const builder: Record<string, unknown> = {
52	      select: vi.fn((...a: unknown[]) => {
53	        recorded.push({ table, method: "select", args: a });
54	        return builder;
55	      }),
56	      eq: vi.fn((...a: unknown[]) => {
57	        recorded.push({ table, method: "eq", args: a });
58	        return builder;
59	      }),
60	      in: vi.fn((...a: unknown[]) => {
61	        recorded.push({ table, method: "in", args: a });
62	        return builder;
63	      }),
64	      order: vi.fn((...a: unknown[]) => {
65	        recorded.push({ table, method: "order", args: a });
66	        return builder;
67	      }),
68	      limit: vi.fn((...a: unknown[]) => {
69	        recorded.push({ table, method: "limit", args: a });
70	        return builder;
71	      }),
72	      single: vi.fn(() => {
73	        recorded.push({ table, method: "single", args: [] });
74	        if (terminal.kind === "insert" || terminal.kind === "select") {
75	          return Promise.resolve({ data: terminal.data ?? null, error: terminal.error ?? null });
76	        }
77	        return Promise.resolve({ data: null, error: terminal.error ?? null });
78	      }),
79	      then: (resolve: (v: { data: unknown; error: unknown }) => void) => {
80	        if (terminal.kind === "insert" || terminal.kind === "select") {
81	          resolve({ data: terminal.data ?? null, error: terminal.error ?? null });
82	        } else {
83	          resolve({ data: null, error: terminal.error ?? null });
84	        }
85	      }
86	    };
87	    return builder;
88	  }
89	
90	  const from = vi.fn((table: string) => {
91	    const cfg = tablesArg[table] ?? {};
92	    return {
93	      insert: vi.fn((...a: unknown[]) => {
94	        recorded.push({ table, method: "insert", args: a });
95	        return makeChain(table, {
96	          kind: "insert",
97	          data: cfg.insert?.data,
98	          error: cfg.insert?.error ?? null
99	        });
100	      }),
101	      update: vi.fn((...a: unknown[]) => {
102	        recorded.push({ table, method: "update", args: a });
103	        return makeChain(table, { kind: "update", error: cfg.update?.error ?? null });
104	      }),
105	      delete: vi.fn((...a: unknown[]) => {
106	        recorded.push({ table, method: "delete", args: a });
107	        return makeChain(table, { kind: "delete", error: cfg.delete?.error ?? null });
108	      }),
109	      select: vi.fn((...a: unknown[]) => {
110	        recorded.push({ table, method: "select", args: a });
111	        return makeChain(table, {
112	          kind: "select",
113	          data: cfg.selectSingle?.data,
114	          error: cfg.selectSingle?.error ?? null
115	        });
116	      })
117	    };
118	  });
119	
120	  const user = opts.user === undefined ? { id: "user_default", email: "user@example.com" } : opts.user;
121	
122	  const supabase = {
123	    from,
124	    auth: {
125	      getUser: vi.fn(async () => ({ data: { user }, error: null }))
126	    }
